 const usable=caps.filter(n=>n>0).length,k=Math.min(5,usable),guidance='No playable exact plan found within the sensible-ladder search. Reduce planned players or reserve, or change buy-in, blinds or inventory. No approximate values were saved.';
 if(!k||caps.slice(0,k).reduce((a,b)=>a+b,0)<8)throw Error(guidance+' At least 8 chips per player are required.');
 let common=gcd(gcd(target,small),big),bases=[small,common,1,2,5,10,20,25,50,100].filter((n,i,a)=>n<=small&&small%n===0&&big%n===0&&target%n===0&&a.indexOf(n)===i),best=null,budget=0,trials=0;
 const factors=[1,2,4,5,10,20,25,50,100,200];
